std::wstring validationText(const J& report){
    std::wstring out=report["passed"].boolean()?L"资源引用与目标格式检查通过\r\n":L"资源检查发现错误，导出已阻止\r\n";
    out+=L"Forge / Minecraft 1.20.1 · 资源格式 15\r\n"+std::to_wstring(report["files"].size())+L" 个文件 · "+std::to_wstring(report["errors"].integer())+L" 个错误 · "+std::to_wstring(report["warnings"].integer())+L" 条提示\r\n\r\n";
    for(auto& row:report["issues"].arr()){out+=(row["severity"].str()=="error"?L"错误 ":L"提示 ")+wide(row["code"].str())+L"\r\n"+wide(row["message"].str())+L"\r\n";if(!row["resource"].null())out+=wide(row["resource"].str())+L"\r\n";out+=L"\r\n";}
    if(!report["forge_runtime"].null()){auto runtime=report["forge_runtime"];out+=L"Forge "+wide(runtime["forge_version"].str())+L" · Java 17 接入\r\n"+std::to_wstring(runtime["part_models"].integer())+L" 个部件模型\r\n";out+=L"项目须提供的实际数据：\r\n"+wide(runtime["required_project_hooks"].dump())+L"\r\n\r\n";}
    out+=L"生效文件与来源\r\n";for(auto& row:report["files"].arr())out+=wide(row["path"].str())+L"\r\n  ← "+wide(row["source"].str())+(row["role"].str()=="dependency"?L"（依赖，仅检查）":L"（项目，可导出）")+L"\r\n";
    if(report["overrides"].size()){out+=L"\r\n覆盖关系\r\n";for(auto& row:report["overrides"].arr()){out+=wide(row["path"].str())+L"\r\n  生效："+wide(row["winner"].str())+L"；覆盖：";for(auto& name:row["shadowed"].arr())out+=wide(name.str())+L" ";out+=L"\r\n";}}
    out+=L"\r\n本次为离线资源检查；不代表已注册新方块、验证全部方块状态或完成游戏内渲染验收。";
    if(!report["generated_sources"].null()){out+=L"\r\n\r\n生成代码与接线预览（只读，尚未正式导出）\r\n";for(auto& [scope,files]:report["generated_sources"].obj())for(auto& [name,content]:files.obj()){out+=L"\r\n["+wide(scope)+L"] "+wide(name)+L"\r\n";for(wchar_t c:wide(content.str())){if(c==L'\n')out+=L'\r';out+=c;}}}
    return out;
}
